  const wantTokens = positiveInt(maxInputTokens);
  if (wantTokens && budget.used.inputTokens + wantTokens > budget.maxInputTokens) { budget.maxInputTokens = budget.used.inputTokens + wantTokens; result.inputTokens = true; }
